/* Categorised emporium. Free gifts use explicit-time, idempotent review receipts. */
const ShopGiftsUI=(()=>{
    const G=MageFreeGifts,categories=[['gifts','Daily gifts','chest-closed'],['cosmetics','Cosmetics','crowned'],['comfort','Comfort','lock']];let serial=0;
    const status=()=>G.status(state.freeGifts,DungeonUI.clock());
    const countdown=()=>{const seconds=Math.max(0,Math.ceil((status().nextAt-DungeonUI.clock())/1000));return Math.floor(seconds/3600)+'h '+String(Math.floor(seconds%3600/60)).padStart(2,'0')+'m';};
    function tabs(){return `<nav class="shop-categories" aria-label="Shop categories">${categories.map(([id,name,art])=>`<button data-shop-category="${id}" aria-pressed="${state.shopCategory===id}">${id==='gifts'?sprite(art):ui(art)}<span>${name}</span>${id==='gifts'&&status().available?'<i class="gift-ready-dot" aria-label="Free gift ready"></i>':''}</button>`).join('')}</nav>`;}
    function gift(){const s=status(),open=!s.available&&s.receipt,opened=state.giftReceipt?.day===s.receipt?.day&&!!s.receipt;return `<section class="daily-gift-card ${open?'gift-collected':''} ${opened?'gift-opened':''}" data-gift-claimed="${!s.available}"><div class="gift-heading"><h3>Daily chest</h3><span class="gift-free-tag">FREE</span></div><div class="gift-figure">${sprite(open?'chest-open':'chest-closed')}${opened?'<span class="gift-reveal-glint" aria-hidden="true">✧</span>':''}</div><div class="gift-reward-preview" aria-label="Daily chest contains 30 Ore and 12 Pearls">${metric('ore','+'+G.definition.ore,'Free gift: '+G.definition.ore+' Ore')}${metric('pearls','+'+G.definition.pearls,'Free gift: '+G.definition.pearls+' Pearls')}</div><button class="rune-button" data-free-gift ${s.available?'':'disabled'}>${s.available?'Open · Free':'✓ Collected'}</button><div class="gift-reset-line">${ui('time','inline-icon')}<span data-gift-reset>${s.available?'One gift each day · 00:00 UTC':'Next gift in '+countdown()}</span></div></section><p class="gift-no-strings">No purchase · No ad · No streak to lose</p>`;}
    function productCard(p){const owned=state.shop.owned.includes(p.id),equipped=state.shop.equipped===p.id;return `<button class="shop-product ${owned?'owned':''}" data-shop-product="${p.id}" aria-label="${p.name}, ${p.type}, ${owned?'owned':p.price+'. Example price'}"><span class="product-sigil sigil-${p.id}">${ui(p.art)}</span><span class="product-copy"><strong>${p.name}</strong><small>${p.type}${p.id==='noAds'?' · Keep forever':''}</small></span><b>${equipped?'Equipped':owned?'Owned':p.price}</b><span aria-hidden="true">›</span></button>`;}
    function view(){const category=state.shopCategory||'gifts';state.shopCategory=category;return `<section class="page shop-page categorised-shop"><div class="compact-heading">${title('Arcane Emporium')}<button class="text-button restore-purchases" data-shop-restore>Restore</button></div>${tabs()}${category==='gifts'?gift():`${category==='cosmetics'?`<div class="shop-mage-preview" data-cosmetic="${state.shop.equipped||''}">${sprite('mage')}<span>${state.shop.equipped?MageShop.products.find(p=>p.id===state.shop.equipped).name:'Your mage, your style'}</span></div>`:`<div class="comfort-preview">${ui('lock')}<span>Play without ad breaks</span></div>`}<div class="shop-products">${MageShop.products.filter(p=>category==='cosmetics'?p.type==='Cosmetic':p.type!=='Cosmetic').map(productCard).join('')}</div><p class="shop-fairness">${ui('crest')} Style & comfort. Strength is earned.</p><small class="shop-demo">Example prices · Purchases are simulated</small>`}</section>`;}
    function handle(el){if(el.dataset.shopCategory){state.shopCategory=el.dataset.shopCategory;render(true);return true;}if(el.hasAttribute('data-free-gift')){const out=G.claim(state,{id:'daily-gift-'+(++serial),now:DungeonUI.clock()});if(out.ok&&!out.duplicate){state.giftReceipt=out.receipt;notify('Daily chest · Collected');}return true;}return false;}
    function tick(){const el=phone.querySelector('[data-gift-reset]');if(!el)return;const s=status(),card=phone.querySelector('.daily-gift-card');if(card.dataset.giftClaimed!==String(!s.available)){render(true);return;}el.textContent=s.available?'One gift each day · 00:00 UTC':'Next gift in '+countdown();}
    return {view,handle,tick,status};
})();
